#include <stdio.h>
#include <stdlib.h>

int is_prime(unsigned long n) {
    if (n <= 1) return 0;
    if (n == 2) return 1;
    if (n % 2 == 0) return 0;
    for (unsigned long i = 3; i * i <= n; i += 2) {
        if (n % i == 0) return 0;
    }
    return 1;
}

int miller_rabin(unsigned long n) {
    if (n < 2) return 0;
    if (n == 2 || n == 3) return 1;
    if (n % 2 == 0) return 0;
    unsigned long s = 0;
    unsigned long d = n - 1;
    while (d % 2 == 0) {
        d /= 2;
        s++;
    }
    unsigned long a[] = {2, 3, 5, 7, 11, 13, 17};
    for (int i = 0; i < 7; i++) {
        unsigned long x = 1;
        for (unsigned long j = 0; j < s; j++) {
            x = (x * a[i]) % n;
        }
        if (x == 1 || x == n - 1) continue;
        for (unsigned long j = 0; j < s - 1; j++) {
            x = (x * x) % n;
            if (x == n - 1) break;
        }
        if (x != n - 1) return 0;
    }
    return 1;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }
    char *endptr;
    unsigned long n = strtoul(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        printf("BAD_INPUT\n");
        return 0;
    }
    if (n > 4294967295) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    if (miller_rabin(n)) {
        printf("PRIME\n");
    } else {
        printf("NOT_PRIME\n");
    }
    return 0;
}
